# v121c: + ss fail-closed (estc), rollback est re-check, N1_IDLE_S default 5 (CR v121b R1, CoS 결정 18:48)
# v121b restart_seller_v121.sh = restart_seller_r3h.sh (sha 9b76d0ba) with: rollback target = the pre_v121 tgz of
#   call_v121_go.sh (seller.py aa1d864a), ROLL_ONLY fixed 0. N1 (est=0 x3, 600 s), prekill re-check, seller-PGID-only
#   SIGTERM, kit watchdog respawn and verify are unchanged. Generated by tools/build_labpc_v121.py (CoS 결정 18:02).
# v120c-B r3h = r3g (a0b85d35) + N1 poll est=0 x3 up to N1_POLL_S (600) + prekill est re-check + restart_seconds (CoS 17:15 (A), no CR). Used without sync.
# v120c-B r3f = r3e kit-pid fix + P0 models_cache.json fallback. r3e = r3d (74784bc8) + kit pid fix: kit = PPID of the seller sh, checked as kit python (argv0 python*, market_kit.py join, in pgrep,
#   other pgrep pids = ancestors e.g. uv wrapper). verify() compares that pid+cmdline. SIGTERM seller PGID only; PRE_TGZ/PRE_SHA unchanged.
# v120c-B r3d = r3c (0dbfc67d) + R1 fix (CR §12): code rollback restores the PRE-SYNC tgz from sync_r3d.sh
#   (PRE_TGZ + PRE_SHA required, sha checked before use, seller.py must be aa1d864a after restore; no ls -t lookup).
#   state/ is never packed, restored or deleted (C3). ROLL_ONLY=1: restore pre-sync tgz + one seller restart, no name write.
# (r3c header follows) v120c-B r3c seller-only restart call (c4 style). NOT SENT. r3c = r3b (cc53ef5a) + name file (option 나, CoS 14:56 / 성수님 14:31)
#   + model-id pre-check. MODE=apply (default): write+verify <seller R3_STATE>/shop_name BEFORE any kill. MODE=revert: rename
#   shop_name -> shop_name.off (no delete), verify absent, restart seller once (CoS pre-approved). Kit/buyer/tmux untouched.
# (r3b header follows) Route: ssh labpc "wsl bash -l -s" < this > out.txt
# Launch facts (box copy market_kit.py 4a0f48b3 L183-186, L1006, L1091-1102; labpc kit version [미확인]):
#   kit (python market_kit.py join ... --name lee-sungsoo --tunnel) spawns the seller with start(): Popen(shell=True,
#   start_new_session=True, cwd=--dir, NO env= -> inherits the KIT os.environ). Seller group = PGID of /bin/sh.
#   kit watchdog (every 60 s) restarts an exited seller with the SAME cmd and the KIT env.
# => SIGTERM to the seller group only; the kit watchdog brings up the new seller (activates the synced seller.py,
#    incl. the v1.20 log version). No manual start (would race the watchdog for port 52605).
# => An env change (R3_SHOP_NAME) CANNOT be done by a seller-only restart: the respawn inherits the kit env.
#    labpc 14:53 read: kit env R3_SHOP_NAME=lee-sungsoo (set explicitly; kit-loop.sh line 6 has no prefix -> tmux session env).
#    Plain restart: SHOP_NAME_WANT=lee-sungsoo. SHOP_NAME_WANT != kit env value -> BLOCKED exit 3 (needs a kit restart = Owner decision). Nothing is killed.
#    r3c: superseded -- the name comes from the name file, the kit env stays lee-sungsoo (no BLOCKED exit).
set -u
W=/home/sungsoo/ai-agent-engineering-101/submissions/25520013/week-09
PORT=52605
SHOP_NAME_WANT="${SHOP_NAME_WANT-LSS Shop}"          # 성수님 14:31 via CoS; goes to the name file, NOT the env
MODE="${MODE-apply}"; MODEL_ID=gpt-6.1-terra; CODEX_VER_WANT=0.164.0; MODEL_REQUIRED="${MODEL_REQUIRED-0}"
ROLL_ONLY=0   # v121b: the r3d ROLL_ONLY path is not used (CoS 결정 18:02)
cd "$W" || { echo "RESULT abort: no W"; exit 2; }
SELLER_PRE=aa1d864a71c3108c57326facd55c809eb16fd358e693770f8291a594a1cde599   # v121b: seller before v121b = rollback target
PRE_TGZ="${PRE_TGZ-}"; PRE_SHA="${PRE_SHA-}"
chk_pre(){ # pre-sync tgz: exists, full sha == PRE_SHA, holds hooks/seller.py == aa1d864a
  [ -n "$PRE_TGZ" ] && [ -n "$PRE_SHA" ] && [ -f "$PRE_TGZ" ] || { echo "RESULT abort: PRE_TGZ/PRE_SHA missing"; return 1; }
  case "$PRE_TGZ" in "$W"/.r3_rollback/pre_v121_*.tgz) ;; *) echo "RESULT abort: PRE_TGZ not a call_v121_go.sh output (.r3/ etc rejected)"; return 1;; esac
  case "$PRE_TGZ" in */.r3/*|*..*) echo "RESULT abort: PRE_TGZ path rejected"; return 1;; esac
  [ "$(sha256sum "$PRE_TGZ" | cut -d" " -f1)" = "$PRE_SHA" ] || { echo "RESULT abort: PRE_TGZ sha mismatch"; return 1; }
  [ "$(tar xzOf "$PRE_TGZ" hooks/seller.py 2>/dev/null | sha256sum | cut -d" " -f1)" = "$SELLER_PRE" ] || { echo "RESULT abort: PRE_TGZ seller.py != aa1d864a"; return 1; }
  tar tzf "$PRE_TGZ" | grep -qE "^(\./)?state(/|$)" && { echo "RESULT abort: PRE_TGZ contains state/"; return 1; }
  return 0; }
chk_pre || exit 2
echo "INFO pre-sync tgz $PRE_TGZ sha=$(echo "$PRE_SHA" | cut -c1-8) seller.py=aa1d864a (checked)"
ts(){ date +%Y%m%dT%H%M%S; }
lpid(){ ss -ltnpH "sport = :$PORT" 2>/dev/null | grep -o "pid=[0-9]*" | head -1 | cut -d= -f2; }
estc(){ o=$(ss -tnH state established "( sport = :$PORT )" 2>/dev/null) || { echo ERR; return; }; [ -n "$(ss -ltnH "sport = :$PORT" 2>/dev/null)" ] || { echo ERR; return; }; if [ -z "$o" ]; then echo 0; else printf "%s\n" "$o" | wc -l | tr -d " "; fi; }   # v121c: ss fail-closed
envv(){ tr "\0" "\n" < /proc/$1/environ 2>/dev/null | grep "^R3_SHOP_NAME=" | cut -d= -f2-; }   # ONE var only
envs(){ tr "\0" "\n" < /proc/$1/environ 2>/dev/null | grep "^R3_STATE=" | cut -d= -f2-; }      # ONE var only (path, not a secret)
KPAT="market_kit.py join .*--name lee-sungsoo"
KITS=$(pgrep -f "$KPAT" | tr "\n" " ")
kcmd(){ tr "\0" " " < /proc/$1/cmdline 2>/dev/null; }
SP=$(lpid); SH=$(ps -o ppid= -p "${SP:-0}" 2>/dev/null | tr -d " ")
# uv sits between sh and python: walk up to the /bin/sh -c ... seller.py process
for _ in 1 2 3; do C=$(tr "\0" " " < /proc/$SH/cmdline 2>/dev/null); case "$C" in "/bin/sh -c "*hooks/seller.py*) break;; esac; SH=$(ps -o ppid= -p "$SH" | tr -d " "); done
# r3e: kit = PPID of the seller sh. labpc: uv wrapper 1148074 -> kit python 1148087 -> sh; r3d took pgrep head -1 = the uv wrapper (rc 2).
KIT=$(ps -o ppid= -p "${SH:-0}" 2>/dev/null | tr -d " "); KPP=$KIT; KCMD="$(kcmd ${KIT:-0})"; WRAP=""
kit_ok(){ # $1: argv0 python*, cmdline = market_kit.py join ... --name lee-sungsoo, $1 in pgrep, every other pgrep pid is an ancestor of $1 (uv wrapper)
  local c a0 p n anc; c="$(kcmd "$1")"; a0="${c%% *}"; a0="${a0##*/}"
  case "$a0" in python|python3|python3.[0-9]*) ;; *) echo "INFO kit_ok: argv0=[$a0] not python"; return 1;; esac
  case "$c" in *"market_kit.py join "*"--name lee-sungsoo"*) ;; *) echo "INFO kit_ok: cmdline not kit"; return 1;; esac
  case " $KITS " in *" $1 "*) ;; *) echo "INFO kit_ok: $1 not in pgrep [$KITS]"; return 1;; esac
  anc=" "; p=$1; for _ in 1 2 3 4 5 6 7 8; do p=$(ps -o ppid= -p "$p" 2>/dev/null | tr -d " "); { [ -z "$p" ] || [ "$p" -le 1 ]; } && break; anc="$anc$p "; done
  for n in $KITS; do [ "$n" = "$1" ] && continue; case "$anc" in *" $n "*) WRAP="$WRAP$n ";; *) echo "INFO kit_ok: pgrep $n is not an ancestor of $1 (second kit?)"; return 1;; esac; done
  return 0; }
SPG=$(ps -o pgid= -p "${SH:-0}" | tr -d " "); KPG=$(ps -o pgid= -p "${KIT:-0}" | tr -d " ")
echo "INFO kit=$KIT kitpgid=$KPG wrapper_pgrep=[$KITS] SP=$SP sh=$SH shpgid=$SPG sh_parent=$KPP"
echo "INFO sh cmd: $(tr "\0" " " < /proc/$SH/cmdline)"
echo "INFO kit cmd: $KCMD"
echo "INFO R3_SHOP_NAME seller=[$(envv $SP)] kit=[$(envv $KIT)]"
[ -n "$KIT" ] && [ -n "$SP" ] && [ -n "$SPG" ] || { echo "RESULT abort: pids"; exit 2; }
kit_ok "$KIT" || { echo "RESULT abort: seller parent is not the kit python"; exit 2; }
echo "INFO kit_ok kit=$KIT wrapper=[$WRAP]"
[ "$SPG" = "$SH" ] && [ "$SPG" != "$KPG" ] && [ "$KPP" = "$KIT" ] || { echo "RESULT abort: seller not a kit child in own group"; exit 2; }
KITNAME="$(envv $KIT)"; [ -z "$KITNAME" ] && KITNAME="lee-sungsoo(default)"
# r3c P0: model id in the labpc codex-cli binary (read-only grep; gates LLM ON by reload, not the restart unless MODEL_REQUIRED=1)
CB=$(command -v codex 2>/dev/null); CB=$(readlink -f "${CB:-/nonexistent}" 2>/dev/null)
CV=$(timeout 10 codex --version 2>/dev/null | head -1)
MH=0; for f in "$CB" $(find "$(dirname "${CB:-/x}")/.." -maxdepth 6 -type f -name "codex*" -size +1M 2>/dev/null | head -5); do
  [ -f "$f" ] && grep -a -q -F "$MODEL_ID" "$f" && { MH=1; MF=$f; break; }; done
[ "$MH" = 0 ] && [ -f "$HOME/.codex/models_cache.json" ] && grep -q -F "$MODEL_ID" "$HOME/.codex/models_cache.json" 2>/dev/null && { MH=1; MF="$HOME/.codex/models_cache.json"; }   # r3f P0 cache fallback (no print)
echo "INFO P0 codex=[$CB] version=[$CV] want=$CODEX_VER_WANT model=$MODEL_ID found=$MH ${MF:+in $MF}"
case "$CV" in *"$CODEX_VER_WANT"*) :;; *) echo "WARN P0 codex version != $CODEX_VER_WANT";; esac
[ "$MH" = 1 ] || { echo "WARN P0 MODEL_UNVERIFIED: hold LLM ON"; [ "$MODEL_REQUIRED" = 1 ] && { echo "RESULT abort: model id"; exit 7; }; }
# N1: quiet shop
# r3h (CoS 17:15 (A)): poll up to N1_POLL_S for est=0 three times in a row (2 s apart); timeout -> exit 4, nothing killed
N1_POLL_S="${N1_POLL_S-600}"; NT0=$(date +%s); Z=0; i=0
while :; do
  i=$((i+1)); E=$(estc)
  [ "$E" = ERR ] && { echo "INFO N1 polls=$i ss_error"; echo "RESULT abort: N1 ss failed (fail-closed, nothing killed)"; exit 4; }
  if [ "$E" = 0 ]; then Z=$((Z+1)); else Z=0; fi
  [ "$Z" -ge 3 ] && break
  [ $(( $(date +%s) - NT0 )) -ge "$N1_POLL_S" ] && { echo "INFO N1 polls=$i last_est=$E"; echo "RESULT abort: N1 established (poll timeout ${N1_POLL_S}s)"; exit 4; }
  sleep 2
done
echo "INFO N1 est=0 x3 after polls=$i waited=$(( $(date +%s) - NT0 ))s"
# r3b: labpc has no logs/buyer_attempts.jsonl (read 14:53); deal activity = last seller metric ts in .r3/metrics.jsonl
LT=$(tail -n 2000 .r3/metrics.jsonl 2>/dev/null | grep -E '"hook": *"seller"' | grep -E '"decision": *"(open|accept|reject|no_stock)"' | tail -1 | grep -o '"ts": *[0-9]*' | grep -o '[0-9]*' | head -1)
[ -n "$LT" ] || { echo "RESULT abort: N1 no seller activity source"; exit 4; }
N1_IDLE_S="${N1_IDLE_S-5}"   # v121c: CoS 결정 18:48 = 5 (go passes N1_IDLE_S=5 explicitly)
[ $(( $(date +%s) - LT )) -ge "$N1_IDLE_S" ] || { echo "RESULT abort: N1 deal activity < ${N1_IDLE_S} s"; exit 4; }
echo "INFO N1 last seller deal metric $(( $(date +%s) - LT )) s ago"
# r3d: no in-script tgz (it would hold the synced code); rollback = PRE_TGZ from sync_r3d.sh
verify(){ # $1 old seller pid
  for _ in $(seq 1 36); do sleep 5; N=$(lpid); [ -n "$N" ] && [ "$N" != "$1" ] && break; done
  N=$(lpid); K2=""; [ -n "$KIT" ] && [ "$(kcmd $KIT)" = "$KCMD" ] && K2=$KIT   # r3e: same kit pid + cmdline (pgrep head -1 = uv wrapper)
  NN=$(timeout 5 curl -s http://127.0.0.1:$PORT/.well-known/agent-card.json 2>/dev/null | grep -o "\"name\": *\"[^\"]*\"" | head -1)
  echo "VERIFY card $NN want=[$SHOP_NAME_WANT]"
  echo "VERIFY newpid=$N listen=$([ -n "$N" ] && echo yes) kit=$K2 tmux=$(tmux has-session -t market 2>/dev/null && echo alive) shoploop=$(pgrep -f shop-loop.sh | head -1)"
  [ -n "$N" ] && [ "$N" != "$1" ] && [ "$K2" = "$KIT" ] && tmux has-session -t market 2>/dev/null
}
if [ "$ROLL_ONLY" != 1 ]; then   # r3d: ROLL_ONLY never writes the name file
# r3c P1 (after N1, right before the kill): name file in the seller state dir (seller cwd = W; R3_STATE from the seller env, default .r3)
ST="$(envs $SP)"; [ -z "$ST" ] && ST=.r3; case "$ST" in /*) :;; *) ST="$W/$ST";; esac
NF="$ST/shop_name"; echo "INFO P1 namefile=$NF mode=$MODE kitenv=[$(envv $KIT)]"
[ -d "$ST" ] || { echo "RESULT abort: no state dir $ST"; exit 3; }
if [ "$MODE" = revert ]; then
  if [ -e "$NF" ]; then OFF="$NF.off"; [ -e "$OFF" ] && OFF="$NF.off.$(ts)"; mv -n "$NF" "$OFF" && echo "ACT renamed $NF -> $OFF"; fi
  [ -e "$NF" ] && { echo "RESULT abort: name file still present"; exit 3; }
  SHOP_NAME_WANT="$(envv $KIT)"
else
  case "$SHOP_NAME_WANT" in ""|*[![:print:]]*) echo "RESULT abort: bad SHOP_NAME_WANT"; exit 3;; esac
  [ ${#SHOP_NAME_WANT} -le 64 ] || { echo "RESULT abort: name > 64"; exit 3; }
  if [ "$(cat "$NF" 2>/dev/null)" != "$SHOP_NAME_WANT" ]; then
    [ -e "$NF" ] && cp -p "$NF" "$NF.bak_$(ts)"
    printf "%s\n" "$SHOP_NAME_WANT" > "$NF.tmp_$$" && mv -f "$NF.tmp_$$" "$NF" && echo "ACT wrote $NF"
  fi
  RB="$(head -c 200 "$NF" 2>/dev/null | tr -d "\n")"
  [ "$RB" = "$SHOP_NAME_WANT" ] || { echo "RESULT abort: name file readback [$RB] != [$SHOP_NAME_WANT]; nothing killed"; exit 3; }
  echo "INFO P1 namefile verified [$RB] sha=$(sha256sum "$NF" | cut -c1-8)"
fi
fi
if [ "$ROLL_ONLY" = 1 ]; then echo "INFO ROLL_ONLY: restore pre-sync tgz + one restart"; NF="${NF:-$( ST="$(envs $SP)"; [ -z "$ST" ] && ST=.r3; case "$ST" in /*) echo "$ST/shop_name";; *) echo "$W/$ST/shop_name";; esac)}"; else
  E=$(estc); echo "INFO prekill est=$E"   # r3h: est re-check right before the kill
  [ "$E" = 0 ] || { echo "RESULT abort: prekill established"; exit 4; }
  KT=$(date +%s); echo "ACT SIGTERM -- -$SPG (seller group only, kit pgid $KPG untouched) $(ts) epoch=$KT"; kill -TERM -- "-$SPG"
  if verify "$SP"; then echo "INFO restart_seconds=$(( $(date +%s) - KT )) newpid_start_epoch=$(( $(date +%s) - $(ps -o etimes= -p "$(lpid)" | tr -d " ") ))"; echo "RESULT ok"; exit 0; fi
  echo "WARN verify failed -> rollback"
fi
# rollback: restore files (state/ never touched), name file -> .off (no delete), restart once; name = kit env (lee-sungsoo)
[ -e "$NF" ] && { OFF="$NF.off"; [ -e "$OFF" ] && OFF="$NF.off.$(ts)"; mv -n "$NF" "$OFF" && echo "ACT renamed $NF -> $OFF"; }
chk_pre || { echo "RESULT rollback_aborted: pre-sync tgz check failed; nothing restored, no more kills"; exit 8; }
tar xzf "$PRE_TGZ" --exclude=state || { echo "RESULT rollback_aborted: untar"; exit 8; }
RS=$(sha256sum hooks/seller.py | cut -d" " -f1)
[ "$RS" = "$SELLER_PRE" ] || { echo "RESULT rollback_bad_sha: seller.py=$(echo $RS | cut -c1-8) != aa1d864a; no kill"; exit 8; }
echo "INFO restored $PRE_TGZ seller.py=aa1d864a"
SP2=$(lpid); SH2=$(ps -o pgid= -p "$(ps -o ppid= -p "${SP2:-0}" | tr -d " ")" 2>/dev/null | tr -d " ")
E2=$(estc); echo "INFO rollback prekill est=$E2"   # v121c: est re-check before the rollback kill
if [ "$E2" != 0 ]; then echo "RESULT rollback_deferred: est=$E2 (files restored on disk, no kill; restart later by procedure)"; exit 6; fi
if [ -n "$SP2" ] && [ -n "$SH2" ] && [ "$SH2" != "$KPG" ]; then kill -TERM -- "-$SH2"; fi
verify "${SP2:-none}" && echo "RESULT rolled_back" || echo "RESULT rollback_unverified (watchdog retries every 60 s; no more kills)"
exit 6
